{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "np.isclose(df['tcprtt'], df['synack'] + df['ackdat'], rtol=1e-3, atol=1e-6)"
      ],
      "features": ["tcprtt", "synack", "ackdat"],
      "rationale": "TCP round-trip time is defined as the sum of synack and ackdat."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['sload'], (df['sbytes'] * 8) / df['dur'], rtol=1e-3, atol=1e-6), True)"
      ],
      "features": ["sload", "sbytes", "dur"],
      "rationale": "Source load is defined as source bits per second, so sload = sbytes*8/dur."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['dload'], (df['dbytes'] * 8) / df['dur'], rtol=1e-3, atol=1e-6), True)"
      ],
      "features": ["dload", "dbytes", "dur"],
      "rationale": "Destination load is defined as destination bits per second, so dload = dbytes*8/dur."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "np.where(df['spkts'] > 0, df['smean'] == df['sbytes'] // df['spkts'], True)",
        "np.where(df['spkts'] > 0, df['smean'] == np.round(df['sbytes'] / df['spkts']), True)",
        "np.where(df['spkts'] > 0, np.abs(df['smean'] - df['sbytes'] / df['spkts']) <= 0.5, True)"
      ],
      "features": ["smean", "sbytes", "spkts"],
      "rationale": "Source mean packet size is defined as total source bytes divided by source packet count."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "np.where(df['dpkts'] > 0, df['dmean'] == df['dbytes'] // df['dpkts'], True)",
        "np.where(df['dpkts'] > 0, df['dmean'] == np.round(df['dbytes'] / df['dpkts']), True)",
        "np.where(df['dpkts'] > 0, np.abs(df['dmean'] - df['dbytes'] / df['dpkts']) <= 0.5, True)"
      ],
      "features": ["dmean", "dbytes", "dpkts"],
      "rationale": "Destination mean packet size is defined as total destination bytes divided by destination packet count."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['spkts'] + df['dpkts']) / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['spkts'] / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['sbytes'] / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['dpkts'] / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], df['dbytes'] / df['dur'], rtol=1e-3, atol=1e-6), True)",
        "np.where(df['dur'] > 0, np.isclose(df['rate'], (df['sbytes'] + df['dbytes']) * 8 / df['dur'], rtol=1e-3, atol=1e-6), True)"
      ],
      "features": ["rate", "spkts", "dpkts", "sbytes", "dbytes", "dur"],
      "rationale": "Rate is undocumented; possible definitions include packets per second, bytes per second, or bits per second, using total or directional counts."
    }
  ]
}
